theorem natRank_closure_insert {S : Set α} (hS : M.IsFlat S) {e : α}
    (he : e ∈ M.E) (heS : e ∉ S) :
    natRank M (M.closure (insert e S)) = natRank M S + 1

theorem exists_hyperplane_superset_notMem (hF : M.IsFlat F) {e : α}
    (heE : e ∈ M.E) (heF : e ∉ F) :
    ∃ H : Set α, IsHyperplane M H ∧ F ⊆ H ∧ e ∉ H

theorem exists_constant_path {F X : Set α} {Γ : Set (Set α)}
    (hX : IsHyperplane M X) (hFX : F ⊆ X) (hXoff : X ∉ Γ) :
    ∃ p : TuttePath M, p.origin = X ∧ p.terminus = X ∧ p.On F ∧ p.Off Γ
